const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.0",
  "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
  "activeProvider": "postgresql",
  "inlineSchema": "// prisma/schema.prisma\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../lib/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ==================== Organización ====================\nmodel School {\n  id               String                @id @default(cuid())\n  name             String\n  branches         Branch[]\n  users            User[]\n  students         Student[]\n  enrollments      Enrollment[]\n  beltRanks        BeltRank[]\n  techniques       Technique[]\n  achievementTypes AchievementType[]\n  plans            Plan[]\n  holidays         Holiday[]\n  examConvocations ExamConvocation[]\n  auditLogs        AuditLog[]\n  reviews          Review[]\n  absencePolicies  SchoolAbsencePolicy[]\n  createdAt        DateTime              @default(now())\n  updatedAt        DateTime              @updatedAt\n}\n\nmodel Branch {\n  id          String       @id @default(cuid())\n  name        String\n  schoolId    String\n  school      School       @relation(fields: [schoolId], references: [id])\n  users       User[]\n  students    Student[]\n  enrollments Enrollment[]\n  classes     Class[]\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n}\n\n// ==================== Usuarios y roles ====================\nenum Role {\n  STUDENT\n  GUARDIAN\n  INSTRUCTOR\n  SCHOOL_ADMIN\n  SUPERADMIN\n}\n\nenum StudentStatus {\n  ACTIVE\n  INACTIVE\n  GRADUATED\n}\n\nenum EnrollmentStatus {\n  PENDING\n  CONTACTED\n  ENROLLED\n  REJECTED\n}\n\nenum ClassEnrollmentStatus {\n  ACTIVE\n  PAUSED\n  ENDED\n  COMPLETED\n}\n\nenum ApprovalStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nenum Gender {\n  MALE\n  FEMALE\n  OTHER\n  PREFER_NOT_TO_SAY\n}\n\nmodel User {\n  id                           String                   @id @default(cuid())\n  email                        String                   @unique\n  emailVerified                DateTime?\n  passwordHash                 String?\n  sessionVersion               Int                      @default(0) // invalida sesiones JWT al cambiar password\n  name                         String?\n  phone                        String?\n  roles                        Role[]                   @default([]) // todos los roles del usuario (multirol)\n  schoolId                     String?\n  school                       School?                  @relation(fields: [schoolId], references: [id])\n  branchId                     String?\n  branch                       Branch?                  @relation(fields: [branchId], references: [id])\n  instructorProfile            InstructorProfile?\n  studentProfile               Student?\n  guardians                    GuardianStudent[]        @relation(\"guardian\")\n  guardianOfStudents           Student[]                @relation(\"primaryGuardian\")\n  rankPromotions               StudentRankHistory[]     @relation(\"rankPromoter\")\n  techniqueEvaluations         TechniqueEvaluation[]    @relation(\"techniqueEvaluator\")\n  techniquesApproved           StudentTechnique[]       @relation(\"techniqueApprovedBy\")\n  achievementsApproved         StudentAchievement[]     @relation(\"achievementApprovedBy\")\n  fitnessReportsApproved       FitnessReport[]          @relation(\"fitnessApprovedBy\")\n  attendanceConfirmations      Attendance[]             @relation(\"attendanceConfirmer\")\n  absenceReviews               AbsenceJustification[]   @relation(\"absenceReviewer\")\n  classSessionsTaken           ClassSession[]           @relation(\"sessionTaker\")\n  emailVerificationTokens      EmailVerificationToken[]\n  passwordResetTokens          PasswordResetToken[]\n  acceptedInvitations          StudentInvitationToken[]\n  notifications                Notification[]\n  pushSubscriptions            PushSubscription[]\n  webauthnCredentials          WebAuthnCredential[]\n  whatsappContact              WhatsAppContact?\n  whatsappMessages             WhatsAppMessage[]\n  auditLogs                    AuditLog[]\n  classes                      Class[]                  @relation(\"instructor\")\n  posts                        Post[]\n  onlineRecoveriesAsInstructor OnlineRecovery[]         @relation(\"onlineRecoveryInstructor\")\n  onlineRecoveriesCreated      OnlineRecovery[]         @relation(\"onlineRecoveryCreator\")\n  createdAt                    DateTime                 @default(now())\n  updatedAt                    DateTime                 @updatedAt\n\n  @@index([schoolId])\n  @@index([branchId])\n}\n\nmodel EmailVerificationToken {\n  id        String    @id @default(cuid())\n  token     String    @unique // hash del token\n  userId    String\n  user      User      @relation(fields: [userId], references: [id])\n  expiresAt DateTime\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([userId])\n}\n\nmodel PasswordResetToken {\n  id        String    @id @default(cuid())\n  token     String    @unique // hash del token\n  userId    String\n  user      User      @relation(fields: [userId], references: [id])\n  expiresAt DateTime\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([userId])\n}\n\nmodel StudentInvitationToken {\n  id           String    @id @default(cuid())\n  token        String    @unique // hash del token\n  studentId    String\n  student      Student   @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  email        String // correo destino de la invitación\n  expiresAt    DateTime\n  usedAt       DateTime?\n  usedByUserId String? // id del User que aceptó la invitación\n  usedBy       User?     @relation(fields: [usedByUserId], references: [id])\n  createdAt    DateTime  @default(now())\n\n  @@index([studentId])\n  @@index([expiresAt])\n}\n\nmodel InstructorProfile {\n  id          String   @id @default(cuid())\n  userId      String   @unique\n  user        User     @relation(fields: [userId], references: [id])\n  bio         String?\n  specialties String[]\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\nmodel Student {\n  id                       String                   @id @default(cuid())\n  userId                   String?                  @unique // si el estudiante tiene cuenta propia (mayor de edad)\n  guardianId               String? // referencia al User tutor (si es menor)\n  schoolId                 String\n  branchId                 String\n  firstName                String\n  lastName                 String\n  dateOfBirth              DateTime\n  gender                   Gender? // género declarado\n  email                    String? // correo de contacto para la invitación de acceso\n  contactPhone             String?\n  medicalInfo              String?\n  emergencyContact         String?\n  giSize                   String? // talla de karategi (uniforme)\n  beltSize                 String? // talla de cinturón\n  enrollmentDate           DateTime                 @default(now())\n  memberNumber             String?                  @unique // matrícula KYU-YYYY-NNN\n  status                   StudentStatus            @default(ACTIVE)\n  currentRank              String? // nombre denormalizado del grado actual (fallback)\n  currentRankId            String? // grado actual (FK al catálogo BeltRank)\n  currentRankRef           BeltRank?                @relation(\"studentCurrentRank\", fields: [currentRankId], references: [id], onDelete: SetNull)\n  photoKey                 String? // clave en Supabase Storage\n  registrationData         Json?\n  planId                   String?\n  plan                     Plan?                    @relation(fields: [planId], references: [id])\n  planStartDate            DateTime? // fecha de inicio en el plan actual (para historial)\n  scholarshipType          ScholarshipType          @default(NONE)\n  scholarshipNote          String? // razón escrita de la beca\n  isCompetitor             Boolean                  @default(false)\n  /**\n   * Si true, el expediente no cuenta en los pendientes \"sin plan/sin horario\".\n   */\n  excludeFromPendingCounts Boolean                  @default(false)\n  school                   School                   @relation(fields: [schoolId], references: [id])\n  branch                   Branch                   @relation(fields: [branchId], references: [id])\n  user                     User?                    @relation(fields: [userId], references: [id])\n  guardian                 User?                    @relation(\"primaryGuardian\", fields: [guardianId], references: [id])\n  guardians                GuardianStudent[]        @relation(\"student\")\n  enrollments              Enrollment[]\n  attendances              Attendance[]\n  absenceJustifications    AbsenceJustification[]\n  achievements             StudentAchievement[]\n  techniques               StudentTechnique[]\n  techniquePracticeLogs    TechniquePracticeLog[]\n  fitnessReports           FitnessReport[]\n  classEnrollments         ClassEnrollment[]\n  rankHistory              StudentRankHistory[]\n  enrollmentApplicant      EnrollmentApplicant?\n  invitationTokens         StudentInvitationToken[]\n  documents                StudentDocument[]\n  notifications            Notification[]\n  onlineRecoveries         OnlineRecovery[]\n  createdAt                DateTime                 @default(now())\n  updatedAt                DateTime                 @updatedAt\n\n  @@index([planId])\n  @@index([scholarshipType])\n  @@index([currentRankId])\n  @@index([branchId])\n  @@index([schoolId])\n  @@index([status])\n  @@index([branchId, status])\n}\n\n// Relación muchos a muchos entre tutores y estudiantes\nmodel GuardianStudent {\n  guardianId   String\n  studentId    String\n  guardian     User     @relation(\"guardian\", fields: [guardianId], references: [id])\n  student      Student  @relation(\"student\", fields: [studentId], references: [id])\n  relationship String? // padre, madre, tutor legal...\n  createdAt    DateTime @default(now())\n\n  @@id([guardianId, studentId])\n}\n\n// ==================== Inscripciones ====================\nenum EnrollmentOrigin {\n  FORM\n  ASSISTANT\n}\n\nenum StudentDocumentType {\n  PROFILE_PHOTO\n  IDENTITY\n  BIRTH_CERTIFICATE\n  PASSPORT\n  MEDICAL_CERTIFICATE\n  OTHER\n}\n\nenum StudentDocumentStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  EXPIRED\n}\n\nenum TechniqueCategory {\n  KIHON\n  KATA\n  KUMITE\n  BUNKAI\n}\n\n// Sub-categorías dentro de Kihon (solo aplican cuando category = KIHON).\nenum KihonCategory {\n  DACHI\n  TSUKI_WAZA\n  UCHI_WAZA\n  GERI_WAZA\n  UKE_WAZA\n  RENZOKU_WAZA\n  IDO_KIHON\n}\n\n// Sub-categorías dentro de Kumite (solo aplican cuando category = KUMITE).\nenum KumiteCategory {\n  GOHON_KUMITE\n  SANBON_KUMITE\n  IPPON_KUMITE\n  JIYU_IPPON_KUMITE\n  JIYU_KUMITE\n  SHIAI_KUMITE\n}\n\nmodel Enrollment {\n  id               String                @id @default(cuid())\n  origin           EnrollmentOrigin\n  schoolId         String?\n  school           School?               @relation(fields: [schoolId], references: [id])\n  branchId         String?\n  branch           Branch?               @relation(fields: [branchId], references: [id])\n  applicantName    String?\n  interest         String? // qué le interesa (karate, defensa personal...)\n  schedule         String? // horario preferido\n  quote            String? // cotización dada\n  studentId        String? // si ya se creó el expediente\n  student          Student?              @relation(fields: [studentId], references: [id])\n  contactEmail     String\n  contactPhone     String?\n  status           EnrollmentStatus      @default(PENDING)\n  notes            String?\n  registrationData Json?\n  applicants       EnrollmentApplicant[]\n  documents        StudentDocument[]\n  createdAt        DateTime              @default(now())\n  updatedAt        DateTime              @updatedAt\n\n  @@unique([contactEmail, status]) // control básico de duplicados\n  @@index([status])\n  @@index([branchId, status])\n}\n\nmodel EnrollmentApplicant {\n  id           String            @id @default(cuid())\n  enrollmentId String\n  studentId    String?           @unique\n  name         String\n  dateOfBirth  DateTime\n  profileData  Json\n  enrollment   Enrollment        @relation(fields: [enrollmentId], references: [id], onDelete: Cascade)\n  student      Student?          @relation(fields: [studentId], references: [id])\n  documents    StudentDocument[]\n  createdAt    DateTime          @default(now())\n  updatedAt    DateTime          @updatedAt\n\n  @@index([enrollmentId])\n}\n\nmodel StudentDocument {\n  id           String                @id @default(cuid())\n  enrollmentId String?\n  applicantId  String?\n  studentId    String?\n  type         StudentDocumentType\n  status       StudentDocumentStatus @default(PENDING)\n  fileName     String\n  storageKey   String                @unique\n  mimeType     String\n  fileSize     Int\n  reviewNotes  String?\n  reviewedAt   DateTime?\n  enrollment   Enrollment?           @relation(fields: [enrollmentId], references: [id], onDelete: SetNull)\n  applicant    EnrollmentApplicant?  @relation(fields: [applicantId], references: [id], onDelete: SetNull)\n  student      Student?              @relation(fields: [studentId], references: [id], onDelete: SetNull)\n  uploadedAt   DateTime              @default(now())\n  updatedAt    DateTime              @updatedAt\n\n  @@index([applicantId])\n  @@index([studentId, status])\n}\n\n// ==================== Rangos y técnicas ====================\nenum Program {\n  ADULT // 18+\n  YOUTH // 11-17\n}\n\n// Día habitual de convocatoria a examen de grado (principiantes sábado, avanzados domingo).\nenum ExamDay {\n  SATURDAY\n  SUNDAY\n}\n\nmodel BeltRank {\n  id                      String               @id @default(cuid())\n  program                 Program              @default(ADULT)\n  name                    String // Blanco, Amarillo, etc.\n  kyuDan                  String? // e.g. \"10TH KYU\", \"SHODAN\"\n  japaneseName            String? // e.g. \"Ju-kyu\", \"Shodan\"\n  kanji                   String? // e.g. \"十級\", \"初段\"\n  order                   Int // orden secuencial dentro del programa\n  beltColor               String? // color del cinturón (hex)\n  beltSecondaryColor      String? // color secundario (franjas)\n  isMaximumRank           Boolean              @default(false)\n  estimatedDurationMonths Int? // duración estimada del grado\n  description             String?\n  schoolId                String?\n  minMonths               Int? // permanencia mínima para examen\n  maxMonths               Int? // permanencia máxima estimada para el grado\n  minAttendancePercent    Int? // asistencia mínima exigida para examen\n  examDay                 ExamDay? // día habitual de convocatoria (null = sin examen definido)\n  school                  School?              @relation(fields: [schoolId], references: [id])\n  katas                   BeltRankKata[]\n  promotions              StudentRankHistory[]\n  currentRankStudents     Student[]            @relation(\"studentCurrentRank\")\n  createdAt               DateTime             @default(now())\n  updatedAt               DateTime             @updatedAt\n}\n\n// Katas requeridas por grado (catálogo M:N). Reutiliza Technique con category KATA.\nmodel BeltRankKata {\n  beltRankId String\n  kataId     String\n  order      Int       @default(0) // posición dentro del grado\n  beltRank   BeltRank  @relation(fields: [beltRankId], references: [id], onDelete: Cascade)\n  kata       Technique @relation(fields: [kataId], references: [id], onDelete: Cascade)\n  createdAt  DateTime  @default(now())\n\n  @@id([beltRankId, kataId])\n  @@index([kataId])\n}\n\nmodel StudentRankHistory {\n  id           String   @id @default(cuid())\n  studentId    String\n  beltRankId   String\n  promotedBy   String?\n  promotedAt   DateTime @default(now())\n  examinerName String? // sensei sinodal / evaluador del examen\n  notes        String?\n  student      Student  @relation(fields: [studentId], references: [id])\n  beltRank     BeltRank @relation(fields: [beltRankId], references: [id])\n  promoter     User?    @relation(\"rankPromoter\", fields: [promotedBy], references: [id])\n  createdAt    DateTime @default(now())\n\n  @@index([studentId, promotedAt])\n  @@index([beltRankId])\n}\n\nmodel Technique {\n  id                 String                 @id @default(cuid())\n  name               String // nombre de la técnica (kata, kihon, etc.)\n  japaneseName       String?\n  kanji              String?\n  description        String?\n  category           TechniqueCategory      @default(KIHON)\n  order              Int                    @default(0) // orden pedagógico dentro del grado\n  kihonCategory      KihonCategory? // kihon: sub-categoría (Dachi, Tsuki Waza...)\n  kumiteCategory     KumiteCategory? // kumite: sub-categoría (Ippon, Jiyu...)\n  movementsCount     Int? // katas: movimientos; kumite: pasos/técnicas; bunkai: secuencias\n  embusen            String? // patrón de desplazamiento (I, H, Cruz...) — solo kata\n  difficulty         String? // Básica, Intermedia, Avanzada\n  videoUrl           String?\n  // Campos específicos por categoría\n  repetitionsCount   Int? // kihon: número de repeticiones\n  stance             String? // kihon: posición / guardia (Zenkutsu Dachi...)\n  level              String? // kihon: nivel (Jodan, Chudan, Gedan)\n  kumiteType         String? // kumite: Kihon Ippon, Jiyu Ippon, Jiyu Kumite, Shiai...\n  distance           String? // kumite: distancia (Toma, Chika Ma, Ma...)\n  role               String? // kumite: rol (Aka, Ao, Tori, Uke)\n  applicationType    String? // bunkai: tipo de aplicación (Defensa personal, Proyección...)\n  originKataId       String? // bunkai: kata de origen\n  originKata         Technique?             @relation(\"BunkaiOrigin\", fields: [originKataId], references: [id], onDelete: SetNull)\n  bunkaiApplications Technique[]            @relation(\"BunkaiOrigin\")\n  schoolId           String?\n  school             School?                @relation(fields: [schoolId], references: [id])\n  beltRankKatas      BeltRankKata[]\n  students           StudentTechnique[]\n  practiceLogs       TechniquePracticeLog[]\n  createdAt          DateTime               @default(now())\n  updatedAt          DateTime               @updatedAt\n\n  @@index([originKataId])\n}\n\nmodel StudentTechnique {\n  id                  String                 @id @default(cuid())\n  studentId           String\n  techniqueId         String\n  student             Student                @relation(fields: [studentId], references: [id])\n  technique           Technique              @relation(fields: [techniqueId], references: [id])\n  approved            Boolean                @default(false)\n  approvedBy          String?\n  approvedByUser      User?                  @relation(\"techniqueApprovedBy\", fields: [approvedBy], references: [id], onDelete: SetNull)\n  approvedAt          DateTime?\n  inPractice          Boolean                @default(false)\n  practiceHours       Float                  @default(0)\n  practiceRepetitions Int                    @default(0) // total acumulado de repeticiones registradas\n  lastPracticeDate    DateTime?\n  notes               String?\n  evaluation          TechniqueEvaluation?\n  practiceLogs        TechniquePracticeLog[]\n  createdAt           DateTime               @default(now())\n\n  @@unique([studentId, techniqueId])\n  @@index([approvedBy])\n}\n\nenum PracticePlace {\n  DOJO\n  FUERA\n}\n\nmodel TechniquePracticeLog {\n  id                 String            @id @default(cuid())\n  // Registro \"asignado\": cuelga del expediente del alumno y acumula repeticiones.\n  studentTechniqueId String?\n  studentTechnique   StudentTechnique? @relation(fields: [studentTechniqueId], references: [id], onDelete: Cascade)\n  // Registro libre (\"diario\"): técnica del catálogo practicada sin estar asignada.\n  // No altera contadores del expediente ni las métricas de grado.\n  studentId          String?\n  student            Student?          @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  techniqueId        String?\n  technique          Technique?        @relation(fields: [techniqueId], references: [id], onDelete: Cascade)\n  date               DateTime          @default(now())\n  repetitions        Int\n  place              PracticePlace     @default(DOJO)\n  notes              String?\n  attendanceId       String?\n  attendance         Attendance?       @relation(fields: [attendanceId], references: [id], onDelete: SetNull)\n  createdAt          DateTime          @default(now())\n\n  @@index([studentTechniqueId, date])\n  @@index([studentId, date])\n  @@index([techniqueId])\n  @@index([attendanceId])\n}\n\nmodel TechniqueEvaluation {\n  id                 String           @id @default(cuid())\n  studentTechniqueId String           @unique\n  score              Float\n  criteria           Json?\n  feedback           String?\n  evaluatedBy        String\n  evaluatedAt        DateTime         @default(now())\n  studentTechnique   StudentTechnique @relation(fields: [studentTechniqueId], references: [id], onDelete: Cascade)\n  evaluator          User             @relation(\"techniqueEvaluator\", fields: [evaluatedBy], references: [id])\n  createdAt          DateTime         @default(now())\n  updatedAt          DateTime         @updatedAt\n\n  @@index([evaluatedBy, evaluatedAt])\n}\n\n// ==================== Clases y asistencia ====================\nenum ClassAudience {\n  ADULTS\n  CHILDREN\n  MIXED\n}\n\nmodel Plan {\n  id           String    @id @default(cuid())\n  name         String\n  description  String?\n  monthlyHours Float     @default(0) // horas mensuales incluidas\n  price        Decimal?  @db.Decimal(10, 2) // valor numérico\n  currency     String    @default(\"DOP\") // moneda del precio (código ISO 4217)\n  isUnlimited  Boolean   @default(false)\n  active       Boolean   @default(true)\n  sortOrder    Int       @default(0)\n  schoolId     String?\n  school       School?   @relation(fields: [schoolId], references: [id])\n  students     Student[]\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@index([active, sortOrder])\n}\n\nmodel Class {\n  id                    String                 @id @default(cuid())\n  name                  String\n  description           String?\n  audience              ClassAudience          @default(MIXED)\n  active                Boolean                @default(true)\n  branchId              String\n  branch                Branch                 @relation(fields: [branchId], references: [id])\n  instructorId          String?\n  instructor            User?                  @relation(\"instructor\", fields: [instructorId], references: [id])\n  dayOfWeek             Int // 0=domingo, 1=lunes...\n  startTime             DateTime               @db.Time // hora de inicio\n  endTime               DateTime               @db.Time // hora de fin\n  sessions              ClassSession[]\n  enrollments           ClassEnrollment[]\n  attendances           Attendance[]\n  absenceJustifications AbsenceJustification[]\n  createdAt             DateTime               @default(now())\n  updatedAt             DateTime               @updatedAt\n\n  @@index([branchId, active])\n}\n\nmodel ClassEnrollment {\n  id         String                @id @default(cuid())\n  classId    String\n  studentId  String\n  status     ClassEnrollmentStatus @default(ACTIVE)\n  enrolledAt DateTime              @default(now())\n  endedAt    DateTime?\n  notes      String?\n  class      Class                 @relation(fields: [classId], references: [id])\n  student    Student               @relation(fields: [studentId], references: [id])\n  createdAt  DateTime              @default(now())\n  updatedAt  DateTime              @updatedAt\n\n  @@unique([classId, studentId])\n  @@index([studentId, status])\n  @@index([classId, status])\n}\n\nmodel ClassSession {\n  id          String       @id @default(cuid())\n  classId     String\n  class       Class        @relation(fields: [classId], references: [id])\n  date        DateTime\n  notes       String?\n  takenById   String? // instructor/admin que cerró el pase de lista\n  takenBy     User?        @relation(\"sessionTaker\", fields: [takenById], references: [id])\n  takenAt     DateTime? // marca que el pase de lista fue completado\n  attendances Attendance[]\n  createdAt   DateTime     @default(now())\n\n  @@unique([classId, date])\n  @@index([takenAt])\n}\n\nenum AbsenceJustificationStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\n/// Qué pasa con el derecho a examen cuando el cuatrimestre cierra con faltas\n/// 3.ª+ sin reponer y el alumno repone después del cierre.\nenum AbsencePostClosePolicy {\n  LOCK_AT_CLOSE\n  RESTORE_ON_RECOVERY\n}\n\n/// Historial de la política por escuela. La política vigente al cierre de un\n/// cuatrimestre es la última fila con effectiveFrom <= fecha de cierre.\nmodel SchoolAbsencePolicy {\n  id            String                 @id @default(cuid())\n  schoolId      String\n  school        School                 @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  policy        AbsencePostClosePolicy @default(LOCK_AT_CLOSE)\n  effectiveFrom DateTime               @default(now())\n  createdAt     DateTime               @default(now())\n\n  @@index([schoolId, effectiveFrom])\n}\n\n/// Motivo de inasistencia reportado por el alumno. Queda pendiente de revisión\n/// por el instructor o el administrador; al aprobarse la sesión queda JUSTIFIED.\nmodel AbsenceJustification {\n  id           String                     @id @default(cuid())\n  studentId    String\n  student      Student                    @relation(fields: [studentId], references: [id])\n  classId      String\n  class        Class                      @relation(fields: [classId], references: [id])\n  date         DateTime // fecha de la clase a la que faltó\n  reason       String\n  status       AbsenceJustificationStatus @default(PENDING)\n  reviewedById String?\n  reviewedBy   User?                      @relation(\"absenceReviewer\", fields: [reviewedById], references: [id])\n  reviewedAt   DateTime?\n  createdAt    DateTime                   @default(now())\n  updatedAt    DateTime                   @updatedAt\n\n  @@unique([studentId, classId, date])\n  @@index([classId, date])\n  @@index([status, date])\n  @@index([studentId, date])\n}\n\nenum AttendanceStatus {\n  PENDING\n  CONFIRMED\n  REJECTED\n  JUSTIFIED\n  ABSENT\n}\n\nenum ScholarshipType {\n  NONE\n  ECONOMIC\n  MERIT\n  COMPETITOR\n}\n\nmodel Attendance {\n  id                       String                 @id @default(cuid())\n  sessionId                String?\n  session                  ClassSession?          @relation(fields: [sessionId], references: [id])\n  studentId                String\n  student                  Student                @relation(fields: [studentId], references: [id])\n  date                     DateTime               @default(now()) // fecha del registro (punch-in o pase de lista)\n  present                  Boolean                @default(true)\n  hoursTrained             Float                  @default(1)\n  sessionType              String?\n  status                   AttendanceStatus       @default(PENDING)\n  classId                  String? // horario en el que asistió efectivamente\n  class                    Class?                 @relation(fields: [classId], references: [id])\n  isOutOfSchedule          Boolean                @default(false) // asistió a un horario distinto al de su referencia\n  recoveredById            String?                @unique // asistencia (fuera de horario) que recuperó una falta justificada\n  recoveredBy              Attendance?            @relation(\"recovery\", fields: [recoveredById], references: [id])\n  recovery                 Attendance?            @relation(\"recovery\")\n  onlineRecoveryAbsence    OnlineRecovery?        @relation(\"onlineRecoveryAbsence\")\n  onlineRecoveryAttendance OnlineRecovery?        @relation(\"onlineRecoveryAttendance\")\n  punchedAt                DateTime               @default(now())\n  confirmedAt              DateTime?\n  confirmedById            String?\n  confirmedBy              User?                  @relation(\"attendanceConfirmer\", fields: [confirmedById], references: [id])\n  notes                    String?\n  practiceLogs             TechniquePracticeLog[]\n  createdAt                DateTime               @default(now())\n  updatedAt                DateTime               @updatedAt\n\n  @@unique([sessionId, studentId])\n  @@index([studentId, date])\n  @@index([status, date])\n  @@index([classId])\n  @@index([isOutOfSchedule])\n}\n\nenum OnlineRecoveryStatus {\n  SCHEDULED\n  COMPLETED\n  CANCELLED\n  NO_SHOW\n}\n\n/// Reposición de una falta mediante una clase online de 35 min acordada.\n/// Al completarse genera una asistencia y enlaza la falta con recoveredById.\nmodel OnlineRecovery {\n  id              String               @id @default(cuid())\n  studentId       String\n  student         Student              @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  absenceId       String               @unique\n  absence         Attendance           @relation(\"onlineRecoveryAbsence\", fields: [absenceId], references: [id], onDelete: Cascade)\n  status          OnlineRecoveryStatus @default(SCHEDULED)\n  scheduledAt     DateTime\n  durationMinutes Int                  @default(35)\n  instructorId    String?\n  instructor      User?                @relation(\"onlineRecoveryInstructor\", fields: [instructorId], references: [id], onDelete: SetNull)\n  meetingUrl      String?\n  costAmount      Decimal?             @db.Decimal(10, 2)\n  costCurrency    String               @default(\"DOP\")\n  costNote        String?\n  costInformedAt  DateTime?\n  attendanceId    String?              @unique\n  attendance      Attendance?          @relation(\"onlineRecoveryAttendance\", fields: [attendanceId], references: [id], onDelete: SetNull)\n  notes           String?\n  createdById     String?\n  createdBy       User?                @relation(\"onlineRecoveryCreator\", fields: [createdById], references: [id], onDelete: SetNull)\n  completedAt     DateTime?\n  cancelledAt     DateTime?\n  createdAt       DateTime             @default(now())\n  updatedAt       DateTime             @updatedAt\n\n  @@index([studentId, status])\n  @@index([scheduledAt])\n  @@index([instructorId])\n}\n\n// ==================== Logros y reportes ====================\nmodel AchievementType {\n  id           String               @id @default(cuid())\n  name         String // \"Cinturón amarillo\", \"Torneo\", etc.\n  description  String?\n  schoolId     String?\n  school       School?              @relation(fields: [schoolId], references: [id])\n  achievements StudentAchievement[]\n  createdAt    DateTime             @default(now())\n\n  @@index([schoolId])\n}\n\nmodel StudentAchievement {\n  id             String          @id @default(cuid())\n  studentId      String\n  student        Student         @relation(fields: [studentId], references: [id])\n  typeId         String\n  type           AchievementType @relation(fields: [typeId], references: [id])\n  evidenceKey    String? // clave en Storage\n  approvedBy     String?\n  approvedByUser User?           @relation(\"achievementApprovedBy\", fields: [approvedBy], references: [id], onDelete: SetNull)\n  comment        String?\n  status         ApprovalStatus  @default(PENDING)\n  achievedAt     DateTime        @default(now())\n  createdAt      DateTime        @default(now())\n\n  @@index([approvedBy])\n}\n\nmodel FitnessReport {\n  id             String         @id @default(cuid())\n  studentId      String\n  student        Student        @relation(fields: [studentId], references: [id])\n  report         String // texto del auto-reporte\n  evidenceKey    String?\n  approvedBy     String?\n  approvedByUser User?          @relation(\"fitnessApprovedBy\", fields: [approvedBy], references: [id], onDelete: SetNull)\n  comment        String?\n  status         ApprovalStatus @default(PENDING)\n  createdAt      DateTime       @default(now())\n\n  @@index([approvedBy])\n}\n\n// ==================== Notificaciones ====================\nenum NotificationType {\n  TECHNIQUES_ASSIGNED\n  TECHNIQUES_REMOVED\n  RANK_PROMOTED\n  KATAS_UNLOCKED\n  CLASS_ENROLLED\n  CLASS_REMOVED\n  PLAN_ASSIGNED\n  SCHOLARSHIP_ASSIGNED\n  DOCUMENT_APPROVED\n  DOCUMENT_REJECTED\n  DOCUMENT_UPLOADED\n  ATTENDANCE_CONFIRMED\n  ATTENDANCE_PUNCHED\n  ATTENDANCE_ABSENCE_REPORTED\n  ATTENDANCE_JUSTIFICATION_REVIEWED\n  ONLINE_RECOVERY_SCHEDULED\n  ONLINE_RECOVERY_RESCHEDULED\n  ONLINE_RECOVERY_COMPLETED\n  ONLINE_RECOVERY_CANCELLED\n  ONLINE_RECOVERY_NO_SHOW\n  ONLINE_RECOVERY_COST_INFORMED\n  ONLINE_RECOVERY_ASSIGNED\n  TECHNIQUE_APPROVED\n  TECHNIQUE_EVALUATED\n  REVIEW_SUBMITTED\n}\n\nenum NotificationPriority {\n  INFO\n  ACTION\n  URGENT\n}\n\nmodel Notification {\n  id        String               @id @default(cuid())\n  userId    String // destinatario (alumno o tutor)\n  user      User                 @relation(fields: [userId], references: [id], onDelete: Cascade)\n  studentId String? // alumno referido por la notificación\n  student   Student?             @relation(fields: [studentId], references: [id], onDelete: SetNull)\n  type      NotificationType\n  title     String\n  body      String\n  link      String? // ruta interna del portal\n  data      Json? // metadatos (techniqueIds, beltRankId, classId...)\n  priority  NotificationPriority @default(INFO)\n  readAt    DateTime?\n  createdAt DateTime             @default(now())\n\n  @@index([userId, readAt])\n  @@index([userId, createdAt])\n  @@index([studentId])\n}\n\n// ==================== WhatsApp ====================\n// Canal de notificaciones vía Meta WhatsApp Cloud API. El contacto guarda el\n// consentimiento (opt-in) y la marca `lastInboundAt`, que define si estamos\n// dentro de la ventana de 24h en la que se permite texto libre. Fuera de esa\n// ventana los envíos iniciados por el negocio usan plantillas aprobadas.\nenum WhatsAppDirection {\n  INBOUND\n  OUTBOUND\n}\n\nenum WhatsAppStatus {\n  QUEUED\n  SENT\n  DELIVERED\n  READ\n  RECEIVED\n  FAILED\n}\n\nmodel WhatsAppContact {\n  id            String            @id @default(cuid())\n  phone         String            @unique // E.164, p. ej. +18296378733\n  userId        String?           @unique\n  user          User?             @relation(fields: [userId], references: [id], onDelete: SetNull)\n  optIn         Boolean           @default(false)\n  optInAt       DateTime?\n  optInSource   String? // registration | profile | enrollment | staff | import\n  optOutAt      DateTime?\n  lastInboundAt DateTime? // abre la ventana de 24h de atención al cliente\n  locale        String            @default(\"es_DO\")\n  messages      WhatsAppMessage[]\n  createdAt     DateTime          @default(now())\n  updatedAt     DateTime          @updatedAt\n\n  @@index([userId])\n}\n\n// Bitácora de mensajes salientes/entrantes. Sirve para trazabilidad, estados\n// de entrega del webhook y para procesar la cola (QUEUED + scheduledFor).\nmodel WhatsAppMessage {\n  id               String            @id @default(cuid())\n  direction        WhatsAppDirection\n  wamid            String?           @unique // id de Meta (wamid.*)\n  contactId        String?\n  contact          WhatsAppContact?  @relation(fields: [contactId], references: [id], onDelete: SetNull)\n  userId           String?\n  user             User?             @relation(fields: [userId], references: [id], onDelete: SetNull)\n  toNumber         String?\n  fromNumber       String?\n  templateName     String?\n  params           Json?\n  body             String?\n  status           WhatsAppStatus    @default(QUEUED)\n  notificationType NotificationType?\n  errorCode        String?\n  scheduledFor     DateTime?\n  sentAt           DateTime?\n  createdAt        DateTime          @default(now())\n  updatedAt        DateTime          @updatedAt\n\n  @@index([contactId, createdAt])\n  @@index([userId])\n  @@index([status, scheduledFor])\n}\n\n// ==================== Web Push ====================\nmodel PushSubscription {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  endpoint  String   @unique\n  p256dh    String\n  auth      String\n  userAgent String?\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n}\n\n// ==================== WebAuthn (ingreso con huella / Face ID) ====================\n// Clave pública de un \"passkey\" registrado por el usuario (huella, rostro o PIN\n// del dispositivo). Solo se guarda la clave pública y un contador de uso; la\n// biometría nunca sale del dispositivo ni llega al servidor. `credentialId` y\n// `publicKey` se almacenan en base64url.\nmodel WebAuthnCredential {\n  id           String    @id @default(cuid())\n  userId       String\n  user         User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  credentialId String    @unique\n  publicKey    String\n  counter      Int       @default(0)\n  transports   String[]  @default([])\n  deviceName   String?\n  deviceType   String? // singleDevice | multiDevice\n  backedUp     Boolean   @default(false)\n  lastUsedAt   DateTime?\n  createdAt    DateTime  @default(now())\n\n  @@index([userId])\n}\n\n// ==================== Calendario dojo (feriados y convocatorias) ====================\nmodel Holiday {\n  id        String   @id @default(cuid())\n  name      String\n  date      DateTime // fecha observada (día no laborable)\n  recurring Boolean  @default(false) // se repite cada año en la misma fecha\n  schoolId  String?\n  school    School?  @relation(fields: [schoolId], references: [id])\n  createdAt DateTime @default(now())\n\n  @@unique([date, schoolId])\n  @@index([schoolId, date])\n}\n\n// Fecha real confirmada de examen. Si no hay una para el cuatrimestre del alumno,\n// se muestra la fecha tentativa calculada desde BeltRank.examDay.\nmodel ExamConvocation {\n  id        String   @id @default(cuid())\n  schoolId  String\n  school    School   @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  date      DateTime\n  examDay   ExamDay\n  label     String?\n  notes     String?\n  confirmed Boolean  @default(false)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([schoolId, date, examDay])\n  @@index([schoolId, date])\n}\n\n// ==================== Reseñas públicas ====================\n// Mensajes positivos que dejan los padres/tutores desde la web. Requieren\n// aprobación del staff antes de mostrarse en el sitio.\nmodel Review {\n  id           String         @id @default(cuid())\n  schoolId     String?\n  school       School?        @relation(fields: [schoolId], references: [id], onDelete: SetNull)\n  authorName   String\n  relationship String?\n  rating       Int            @default(5)\n  message      String\n  email        String?\n  status       ApprovalStatus @default(PENDING)\n  approvedAt   DateTime?\n  createdAt    DateTime       @default(now())\n  updatedAt    DateTime       @updatedAt\n\n  @@index([schoolId, status])\n  @@index([status, createdAt])\n}\n\n// Tabla para rate limiting simple por ventana fija. `key` identifica la acción\n// (p. ej. \"login:{ip}\", \"forgot:{email}\") y `windowStart` es el inicio de la\n// ventana actual; `count` acumula los intentos en esa ventana.\nmodel ApiUsage {\n  id          String   @id @default(cuid())\n  key         String\n  windowStart DateTime\n  count       Int      @default(1)\n  updatedAt   DateTime @updatedAt\n\n  @@unique([key, windowStart])\n  @@index([key])\n}\n\n// Trazabilidad de acciones sensibles del staff (exports, borrados): soporta\n// repudio/responsabilidad. El `detail` es un JSON opcional con el contexto.\nmodel AuditLog {\n  id         String   @id @default(cuid())\n  schoolId   String?\n  school     School?  @relation(fields: [schoolId], references: [id], onDelete: SetNull)\n  actorId    String\n  actor      User     @relation(fields: [actorId], references: [id])\n  action     String\n  targetType String?\n  targetId   String?\n  detail     Json?\n  ip         String?\n  createdAt  DateTime @default(now())\n\n  @@index([actorId])\n  @@index([schoolId, createdAt])\n  @@index([action])\n}\n\n// ==================== Blog ====================\n// Artículos del blog. El contenido se guarda en Markdown y se renderiza en el\n// servidor con react-markdown (sin HTML crudo, por seguridad).\nenum PostCategory {\n  FILOSOFIA\n  GUIA_PARA_PADRES\n  TESTIMONIOS\n  EDUCATIVO\n}\n\nmodel Post {\n  id            String       @id @default(cuid())\n  title         String\n  slug          String       @unique // generado a partir del título (único)\n  excerpt       String // resumen corto para el listado\n  content       String // Markdown\n  coverImageUrl String?\n  coverImageKey String? // clave en Supabase Storage (para poder borrar la imagen)\n  category      PostCategory\n  published     Boolean      @default(false)\n  publishedAt   DateTime?\n  authorId      String\n  author        User         @relation(fields: [authorId], references: [id])\n  createdAt     DateTime     @default(now())\n  updatedAt     DateTime     @updatedAt\n\n  @@index([published, publishedAt])\n  @@index([category, published, publishedAt])\n}\n"
}

